def give_ref_codes(apps, schema_editor):
    """Each existing subscriber gets its own share code (a callable default runs once for every row)."""
    Subscriber = apps.get_model("z_blog", "NewsletterSubscriber")
    used = set()
    for sub in Subscriber.objects.all().only("id"):
        code = z_blog.models.new_ref_code()
        while code in used:
            code = z_blog.models.new_ref_code()
        used.add(code)
        Subscriber.objects.filter(pk=sub.pk).update(ref_code=code)


